#!/usr/bin/env bash
# DJB lineup advisor installer for the Pi. Run as your normal user:  bash install.sh
set -euo pipefail
DIR="$HOME/fantasy-lineup"
U="$(id -un)"

echo "==> Checking Python"
python3 -c 'import sys; assert sys.version_info >= (3, 9), sys.version' \
  || { echo "Need Python 3.9+"; exit 1; }
python3 -m venv --help >/dev/null 2>&1 || sudo apt-get install -y python3-venv

echo "==> Installing to $DIR"
mkdir -p "$DIR" && cd "$DIR"
echo "" | base64 -d > lineup_advisor.py
chmod 755 lineup_advisor.py
[ -d .venv ] || python3 -m venv .venv
.venv/bin/pip install -q --upgrade pip
.venv/bin/pip install -q yahoo_fantasy_api yahoo_oauth requests

if ! grep -q refresh_token oauth2.json 2>/dev/null; then
  echo "==> Yahoo app keys (from developer.yahoo.com/apps, app djb-lineup)"
  read -rp  "Client ID: " CID
  read -rsp "Client Secret (hidden): " CSEC; echo
  umask 077
  printf '{\n  "consumer_key": "%s",\n  "consumer_secret": "%s",\n  "callback_uri": "https://localhost:8080"\n}\n' "$CID" "$CSEC" > oauth2.json
  chmod 600 oauth2.json
  echo
  echo "==> One-time Yahoo sign-in"
  echo "Open the URL below, approve, then copy the code= value from the"
  echo "address bar of the page that fails to load (https://localhost:8080/?code=...)."
  .venv/bin/python -W ignore -c "from yahoo_oauth import OAuth2; OAuth2(None, None, from_file='oauth2.json', browser_callback=False)"
fi

if [ ! -f .env ]; then
  TOPIC="djb-lineup-$(head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n' | cut -c1-12)"
  umask 077
  echo "NOTIFY_URL=https://ntfy.sh/$TOPIC" > .env
  chmod 600 .env
fi

echo "==> Installing systemd timer (needs sudo)"
sudo tee /etc/systemd/system/fantasy-lineup.service >/dev/null <<UNIT
[Unit]
Description=DJB lineup advisor (read-only)
Wants=network-online.target
After=network-online.target

[Service]
Type=oneshot
User=$U
WorkingDirectory=$DIR
EnvironmentFile=-$DIR/.env
ExecStart=$DIR/.venv/bin/python -W ignore $DIR/lineup_advisor.py
UNIT
sudo tee /etc/systemd/system/fantasy-lineup.timer >/dev/null <<UNIT
[Unit]
Description=Run DJB lineup advisor twice a day

[Timer]
OnCalendar=*-*-* 09:00:00 America/Chicago
OnCalendar=*-*-* 16:30:00 America/Chicago
Persistent=true
RandomizedDelaySec=120

[Install]
WantedBy=timers.target
UNIT
sudo systemctl daemon-reload
sudo systemctl enable --now fantasy-lineup.timer

echo
echo "==> Test run (prints only, no alert)"
.venv/bin/python -W ignore lineup_advisor.py --print || true
echo
echo "Done. Next runs:"; systemctl list-timers fantasy-lineup.timer --no-pager | head -3
echo
echo "Phone alerts: install the ntfy app and subscribe to this topic:"
grep NOTIFY_URL .env | cut -d= -f2
